// Fail-closed auth: reject unless ?t= matches VIO_WEBHOOK_TOKEN. No env set at all = reject
// everything, not "allow everything" — same rule as VIO-inbound-reply-to-call, and it matters
// just as much here: a forged engagement event would tell a human a cold lead is hot.
//
// Sendr also sends its own generated secret in X-Webhook-Secret. That is checked as a SECOND
// factor when VIO_SENDR_WEBHOOK_SECRET is set on the host, but it is deliberately not the primary
// gate — the URL token is the one we control and rotate.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');

const sendrSecret = $env.VIO_SENDR_WEBHOOK_SECRET;
if (sendrSecret) {
  const sent = headers['x-webhook-secret'];
  if (!sent || String(sent) !== String(sendrSecret)) {
    throw new Error('REFUSED: X-Webhook-Secret mismatch');
  }
}
return { json: item.body || item };

// Classify a Sendr page/engagement event into a heat level, and recover WHICH LEAD it is.
//
// A Sendr engagement event is otherwise anonymous — it says "page 3791582 was viewed", not who.
// The lead identity comes back only because the generate step stamps `attributes` on the page and
// Sendr echoes them on every event. Verified live 2026-08-10: Sendr CAMELCASES those keys on the
// way back (`lead_email` was returned as `leadEmail`), so both casings are read here — a page
// generated by hand in the Sendr UI may carry either.
//
// TCPA — read before changing anything below: nothing in this workflow may trigger a call.
// A page view, a button click, even a booking is NOT the confirmed positive reply that
// VIO-inbound-reply-to-call gates on. This workflow's ceiling is telling a human. That is the
// whole design, not a limitation to be optimised away later.
const p = $input.item.json;
const evt = String(p.eventType || p.event_type || '');
const attrs = p.attributes || {};
const pick = (...names) => { for (const n of names) if (attrs[n]) return attrs[n]; return null; };

const lead = {
  email: pick('leadEmail', 'lead_email'),
  name: pick('leadName', 'lead_name'),
  company: pick('company'),
  product: pick('product'),
  campaign: pick('sendrCampaignId', 'sendr_campaign_id'),
};

// Idempotency. Sendr retries on non-2xx and the deprecated aliases double up with the new event
// names, so the same real action can arrive more than once.
const data = $getWorkflowStaticData('node');
data.seen = data.seen || [];
const key = `${p.pageId || p.pageSlug || '?'}:${evt}:${p.timestamp || ''}`;
if (data.seen.includes(key)) {
  return { json: { decision: 'skip', heat: 'duplicate', reason: 'already handled this exact event', lead, event: evt, pageUrl: p.pageUrl } };
}
data.seen.push(key);
if (data.seen.length > 5000) data.seen.shift();

// Sendr's event families, mapped to what a human should actually do about them.
const HEAT = {
  'engagement:meeting_booked': 'booked',
  'engagement:button_click': 'hot',
  'engagement:video_play': 'hot',
  'engagement:audio_play': 'hot',
  'engagement:video_comment': 'hot',
  'engagement:video_emoji_click': 'hot',
  'engagement:page_view': 'warm',
  'page:done': 'asset_ready',
  'page:failed': 'error',
  'page:pending': 'quiet',
  // Deprecated aliases Sendr still emits alongside the new names.
  'page_render:created': 'quiet',
  'page_render:updated': 'quiet',
  'page_render:deleted': 'quiet',
  'contact_page_engagement:created': 'warm',
  'contact_page_engagement:updated': 'warm',
};
let heat = HEAT[evt] || 'unknown';

// `page:failed` does NOT mean the page is unusable. Verified live 2026-08-10: pages whose GIF task
// failed still return HTTP 200 and render correctly — only the optional asset is missing. Telling
// a rep to withhold a working link costs a real send, so the two cases are separated here.
// Sendr's own reason string names the failing sub-task, e.g.
//   "pageGifTask: missing recordingFileUrl (no quick link or template video)"
// NOTE: that string arrives ONLY on this webhook. GET /api/v1/pages/{id} returns
// errorMessage: null for the very same page — so this node is the only place the real diagnosis
// exists. Do not "simplify" it by re-fetching the page.
const reason = String(p.errorMessage || p.failureMessage || '');
const failedTask = (reason.match(/^([a-zA-Z]+Task)\b/) || [])[1] || null;
const assetOnly = heat === 'error' && !!p.pageUrl &&
  /gif|audio|lipsync|background/i.test(reason);
if (assetOnly) heat = 'asset_warning';

const who = `${lead.name || 'Unknown lead'}${lead.company ? ' at ' + lead.company : ''}`;
const notify = ['booked', 'hot', 'error', 'asset_warning'].includes(heat);

let slack_text = '';
if (heat === 'booked') {
  slack_text = `:calendar: *Meeting booked from a Sendr page* — ${who}\n` +
    `Product: ${lead.product || 'unknown'} · ${lead.email || 'no email on file'}\n` +
    `Page: ${p.pageUrl || 'n/a'}\n` +
    `This is the goal state. Confirm it landed in the calendar and take it from here.`;
} else if (heat === 'hot') {
  slack_text = `:fire: *Sendr page engagement* — ${who}\n` +
    `Did: \`${evt}\` · Product: ${lead.product || 'unknown'} · ${lead.email || 'no email on file'}\n` +
    `Page: ${p.pageUrl || 'n/a'}\n` +
    `Intent signal only — not a reply, and not consent to call. Worth a human look.`;
} else if (heat === 'asset_warning') {
  slack_text = `:art: *Sendr asset didn't render* (the page itself is fine) — ${who}\n` +
    `Page: ${p.pageUrl} — this link works, send it.\n` +
    `Missing: \`${failedTask || 'an optional asset'}\` · ${reason || 'no reason given'}\n` +
    `Only the embedded asset is absent. If it says "missing recordingFileUrl", the page template ` +
    `has a GIF element but no recorded video — record one in the Sendr template, or remove the ` +
    `GIF element. Not a Sendr support issue.`;
} else if (heat === 'error') {
  slack_text = `:warning: *A Sendr page failed to render* — ${who}\n` +
    `Page: ${p.pageUrl || p.pageId || 'n/a'} · ${reason || 'no reason given'}\n` +
    `No usable page URL came back. Do not send this lead a link until it is regenerated.`;
}

return { json: {
  decision: notify ? 'notify_human' : 'log_only',
  heat, event: evt, lead, failed_task: failedTask,
  pageId: p.pageId || null, pageUrl: p.pageUrl || null, gifUrl: p.gifUrl || null,
  eventStatus: p.eventStatus || null,
  slack_text,
  reason: notify ? 'engagement or failure a human should see' : `heat "${heat}" — recorded, no action`,
} };
